import os
import pandas as pd
from dateutil.parser import parse
import matplotlib.pyplot as plt
from datetime import date, datetime

OUTPUT_DIR = './output'

def task_func(csv_path=os.path.join(OUTPUT_DIR, 'data.csv'), date_column='date'):
    df = pd.read_csv(csv_path)

    if date_column not in df.columns:
        raise KeyError(f"Column '{date_column}' not found in CSV file.")

    def _parse_date_value(value):
        if pd.isna(value):
            return pd.NaT

        if isinstance(value, (pd.Timestamp, datetime, date)):
            try:
                return pd.Timestamp(value).to_pydatetime()
            except Exception:
                return pd.NaT

        if isinstance(value, str):
            text = value.strip()
            if not text:
                return pd.NaT
            try:
                return parse(text)
            except Exception:
                return pd.NaT

        try:
            return parse(str(value))
        except Exception:
            return pd.NaT

    parsed_dates = df[date_column].apply(_parse_date_value)
    years = [dt.year for dt in parsed_dates if not pd.isna(dt)]

    fig, ax = plt.subplots()

    if years:
        min_year = min(years)
        max_year = max(years)
        ax.hist(years, bins=range(min_year, max_year + 2), edgecolor='black')
    else:
        ax.hist([], bins=1)
        ax.text(
            0.5,
            0.5,
            'No valid dates found',
            ha='center',
            va='center',
            transform=ax.transAxes,
        )

    ax.set_xlabel('Year')
    ax.set_ylabel('Count')
    ax.set_title('Distribution of Years')

    return ax
